method Strongest_Extension(class_name: string, extensions: seq<string>) returns (result: string)
    requires class_name != ""
    requires extensions != []
    ensures result == class_name + "." + strongest_extension
    ensures strongest_extension in extensions
    ensures forall e: string :: e in extensions && strength(e) == max_strength ==> e == strongest_extension
{
    var max_strength := -999; // Initialize to a very low value
    var strongest_extension := ""; // Variable to store the name of the strongest extension

    // Iterate through each extension to determine its strength
    var i := 0;
    while i < |extensions|
        invariant 0 <= i <= |extensions|
        invariant strongest_extension in extensions || strongest_extension == ""
        invariant max_strength >= -999
    {
        var current_extension := extensions[i];
        var cap := CountUpperCase(current_extension);
        var sm := CountLowerCase(current_extension);
        var strength := cap - sm;

        if strength > max_strength {
            max_strength := strength;
            strongest_extension := current_extension;
        }

        i := i + 1;
    }

    result := class_name + "." + strongest_extension;
}

// Helper function to count uppercase letters in a string
function CountUpperCase(s: string): int
    requires s != ""
    ensures 0 <= CountUpperCase(s) <= |s|
{
    var count := 0;
    var i := 0;
    while i < |s|
        invariant 0 <= i <= |s|
        invariant count == CountUpperCase(s[..i])
    {
        if s[i] >= 'A' && s[i] <= 'Z' {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

// Helper function to count lowercase letters in a string
function CountLowerCase(s: string): int
    requires s != ""
    ensures 0 <= CountLowerCase(s) <= |s|
{
    var count := 0;
    var i := 0;
    while i < |s|
        invariant 0 <= i <= |s|
        invariant count == CountLowerCase(s[..i])
    {
        if s[i] >= 'a' && s[i] <= 'z' {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}
